/**
 * The fake data lab mode serves.
 *
 * Every export is declared as the type the OpenAPI spec generates for the
 * endpoint that returns it (`Json200<path, method>` below, resolved from
 * `api/schema.d.ts`, regenerated by `bun run generate:api`). That is the whole
 * guarantee of this file: when the API adds, renames or drops a field,
 * `bun run typecheck` fails HERE, so the lab cannot quietly keep showing a
 * shape the backend stopped returning.
 */
import type { paths, components } from "../api/schema";
import {
  resolveIntegrationToolSurface,
  type IntegrationManifest,
  type IntegrationToolCatalogEntry,
} from "@appstrate/core/integration";

export type Json200<P extends keyof paths, M extends keyof paths[P]> = paths[P][M] extends {
  responses: { 200: { content: { "application/json": infer B } } };
}
  ? B
  : never;

export type JsonRequest<P extends keyof paths, M extends keyof paths[P]> = paths[P][M] extends {
  requestBody: { content: { "application/json": infer B } };
}
  ? B
  : never;

export const ORG_ID = "org_lab";
export const APP_ID = "app_lab";
export const USER_ID = "user_lab";

/**
 * Clock anchor: the current hour, truncated. Screenshots stay identical across
 * reloads within the hour (so a visual diff is a real diff), while "started 2
 * minutes ago" still reads as 2 minutes to the UI, which computes elapsed time
 * against the live clock. A hard-coded date drifts and shows a live run as
 * having been going for hours.
 */
const T0 = Math.floor(Date.now() / 3_600_000) * 3_600_000;
const ago = (minutes: number) => new Date(T0 - minutes * 60_000).toISOString();

