/** Who reaches which space: Julie only where she was seated, Camille through the open spaces. */
export function membersOfSpace(spaceId: string): SpaceMember[] {
  if (spaceId === "app_lab_sandbox")
    return spaceMembers.filter((member) => member.org_role !== "guest");
  if (spaceId === APP_ID)
    return spaceMembers.map((member) =>
      member.email === "julie@cabinet-martin.fr"
        ? { ...member, role: { kind: "preset", key: "viewer", name: "viewer" } }
        : member,
    );
  return spaceMembers;
}

/**
 * What is ACTIVE in a space — the lab's `space_packages`. The library says
 * where each package is installed, and a system package counts everywhere,
 * the same rule the real list routes apply.
 */
export function activePackageIds(
  type: "agent" | "skill" | "mcp-server" | "integration",
  spaceId: string,
): Set<string> {
  return new Set(
    library.packages[type]
      .filter(
        (pkg) =>
          pkg.source === "system" ||
          pkg.placements.some(
            (placement) => placement.space_id === spaceId && placement.state === "active",
          ),
      )
      .map((pkg) => pkg.id),
  );
}

