function runtimeToolRows(tool: string, args: unknown, body: unknown) {
  const data = (extra: object) =>
    ({
      tool,
      toolCallId: `call_${tool}`,
      ...extra,
    }) as unknown as components["schemas"]["RunLog"]["data"];
  return [
    {
      id: 0,
      runId: "run_01",
      type: "progress",
      level: "info",
      event: "tool.call",
      message: `Tool: ${tool}`,
      data: data({ args }),
      createdAt: ago(1),
    },
    {
      id: 0,
      runId: "run_01",
      type: "progress",
      level: "info",
      event: "tool.result",
      message: `Tool result: ${tool}`,
      data: data({
        isError: false,
        result: { content: [{ type: "text", text: JSON.stringify(body) }] },
        durationMs: 180,
      }),
      createdAt: ago(1),
    },
  ] as const;
}

